code.java:
class Solution {
    public int countGoodSubstrings(String s){
        int answer=0;
        for(int i=0;i+2<s.length();i++)if(s.charAt(i)!=s.charAt(i+1)&&s.charAt(i)!=s.charAt(i+2)&&s.charAt(i+1)!=s.charAt(i+2))answer++;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun countGoodSubstrings(s:String):Int{
        var answer=0;
        for(i in 0..s.length-3)if(s[i]!=s[i+1]&&s[i]!=s[i+2]&&s[i+1]!=s[i+2])answer++;
        return answer
    }
}

code.cpp:
class Solution {
    public: int countGoodSubstrings(string s){
        int answer=0;
        for(int i=0;i+2<(int)s.size();++i)if(s[i]!=s[i+1]&&s[i]!=s[i+2]&&s[i+1]!=s[i+2])++answer;
        return answer;
    }
};
